//! Tailwind's default color palette (proposal §16's "token resolution",
//! done for the default palette only -- theme customization / arbitrary
//! colors are still out of scope, staying unresolved as before).
//!
//! Extracted from the real `tailwindcss` npm package (v4.3.3)'s
//! `theme.css`, converted oklch -> hex via the `culori` library -- not
//! hand-transcribed, to avoid transcription errors across 288
//! entries. Regenerate by re-running the extraction script if Tailwind's
//! palette changes; this file is generated output, not hand-maintained.

/// A color resolved to both representations each backend needs: `oklch`
/// is emitted as-is on Web (byte-for-byte what Tailwind's own CSS would
/// produce), `hex` is what Native uses since RN's style system doesn't
/// understand the `oklch()` CSS function.
pub struct ResolvedColor {
    pub oklch: &'static str,
    pub hex: &'static str,
}

