#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn resolves_known_tokens() {
        let blue = resolve_color_token("blue-500").expect("blue-500 is in the default palette");
        assert_eq!(blue.hex, "#2b7fff");
        assert!(blue.oklch.starts_with("oklch("));

        assert_eq!(resolve_color_token("black").unwrap().hex, "#000");
        assert_eq!(resolve_color_token("white").unwrap().hex, "#fff");
    }

    #[test]
    fn unknown_token_resolves_to_none() {
        assert!(resolve_color_token("brand-primary").is_none());
        assert!(resolve_color_token("blue-501").is_none());
    }
}
